/**
 * Art direction: one palette + one sun for the whole scene, so the ocean,
 * sky, bird and board all read as the same late-afternoon moment.
 */
import * as THREE from "three";

export const PALETTE = {
  zenith:      "#1d5f96",
  midSky:      "#63a7c9",
  horizonSky:  "#f3c391",
  sunCore:     "#fff6df",
  sunGlow:     "#ffb765",

  deepWater:   "#04303f",
  midWater:    "#0a6a80",
  shallowWater:"#1fa8a3",
  crest:       "#8fe3dd",
  foam:        "#fdfaf3",
  haze:        "#e8b489",

  body:        "#f8f4ea",
  bodyShade:   "#ded3c2",
  wingTip:     "#33343c",
  beak:        "#f6bd45",
  beakTip:     "#e08a3c",
  pouch:       "#f2976b",
  leg:         "#f09a4d",
  eye:         "#1a1618",

  boardDeck:   "#f7efe1",
  boardBottom: "#e4553c",
  boardStripe: "#17a2a2",
  boardRail:   "#22303a",
  fin:         "#1c2a33",
};

export const C = Object.fromEntries(
  Object.entries(PALETTE).map(([k, v]) => [k, new THREE.Color(v)])
);

/** Low warm sun, off to the left and slightly behind the wave. */
export const SUN_DIR = new THREE.Vector3(-0.62, 0.235, -0.75).normalize();

export const SUN_COLOR = new THREE.Color("#ffd7a1");
export const SKY_LIGHT = new THREE.Color("#7fb6d8");
export const BOUNCE_LIGHT = new THREE.Color("#3fa8a0");

/** Direction the swell is mostly travelling in (used for board heading). */
export const SWELL_HEADING = new THREE.Vector3(1, 0, 0.18).normalize();

import * as THREE from "three";
import { PALETTE } from "./palette.js";

/**
 * Sky dome: vertical gradient + sun disc + wide golden bloom + a horizon haze
 * band that matches the ocean fog colour exactly, so sea and sky melt into
 * each other. No textures — everything is evaluated in the shader.
 */
export function createSky(sunDir) {
  const uniforms = {
    uSunDir: { value: sunDir.clone() },
    uZenith: { value: new THREE.Color(PALETTE.zenith) },
    uMid: { value: new THREE.Color(PALETTE.midSky) },
    uHorizon: { value: new THREE.Color(PALETTE.horizonSky) },
    uHaze: { value: new THREE.Color(PALETTE.haze) },
    uSunCore: { value: new THREE.Color(PALETTE.sunCore) },
    uSunGlow: { value: new THREE.Color(PALETTE.sunGlow) },
    uTime: { value: 0 },
  };

  const material = new THREE.ShaderMaterial({
    uniforms,
    side: THREE.BackSide,
    depthWrite: false,
    depthTest: false,
    fog: false,
    vertexShader: /* glsl */ `
      varying vec3 vDir;
      void main() {
        vDir = normalize(position);
        gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
        gl_Position.z = gl_Position.w;   // pin to the far plane
      }
    `,
    fragmentShader: /* glsl */ `
      precision highp float;
      uniform vec3 uSunDir, uZenith, uMid, uHorizon, uHaze, uSunCore, uSunGlow;
      uniform float uTime;
      varying vec3 vDir;

      float hash(vec2 p) {
        return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453123);
      }
      float vnoise(vec2 p) {
        vec2 i = floor(p), f = fract(p);
        f = f * f * (3.0 - 2.0 * f);
        float a = hash(i), b = hash(i + vec2(1.0, 0.0));
        float c = hash(i + vec2(0.0, 1.0)), d = hash(i + vec2(1.0, 1.0));
        return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
      }

      void main() {
        vec3 dir = normalize(vDir);
        float h = dir.y;

        // --- vertical gradient -------------------------------------------
        vec3 col = mix(uHorizon, uMid, smoothstep(0.0, 0.22, h));
        col = mix(col, uZenith, smoothstep(0.14, 0.85, h));

        // warm band hugging the horizon
        float band = exp(-abs(h) * 13.0);
        col = mix(col, uHaze, band * 0.55);

        // --- sun ----------------------------------------------------------
        float sd = max(dot(dir, uSunDir), 0.0);
        float disc = smoothstep(0.99885, 0.99945, sd);
        float core = pow(sd, 900.0);
        float glow = pow(sd, 42.0);
        float wide = pow(sd, 6.0);
        col += uSunCore * (disc * 3.2 + core * 1.6);
        col += uSunGlow * (glow * 0.55 + wide * 0.16);

        // --- soft cloud wisps (procedural, drift slowly) -------------------
        if (h > 0.005) {
          vec2 uv = dir.xz / (h + 0.14);
          float t = uTime * 0.006;
          float n = vnoise(uv * 0.55 + vec2(t, -t * 0.6));
          n += 0.5 * vnoise(uv * 1.7 + vec2(-t * 1.7, t * 0.9));
          n += 0.25 * vnoise(uv * 4.3 + vec2(t * 2.3, t * 1.1));
          n /= 1.75;
          float wisp = smoothstep(0.52, 0.92, n) * smoothstep(0.005, 0.16, h) * (1.0 - smoothstep(0.34, 0.9, h));
          vec3 cloudCol = mix(vec3(1.0, 0.87, 0.76), vec3(1.0, 0.98, 0.94), smoothstep(0.0, 0.3, h));
          cloudCol += uSunGlow * pow(sd, 8.0) * 0.5;
          col = mix(col, cloudCol, wisp * 0.5);
        }

        // --- below the horizon: pure haze so it meets the fogged sea -------
        col = mix(col, uHaze * 0.92, smoothstep(0.0, -0.10, h));

        gl_FragColor = vec4(col, 1.0);
        #include <tonemapping_fragment>
        #include <colorspace_fragment>
      }
    `,
  });

  const mesh = new THREE.Mesh(new THREE.SphereGeometry(1, 32, 20), material);
  mesh.scale.setScalar(9000);
  mesh.frustumCulled = false;
  mesh.renderOrder = -1000;
  mesh.name = "sky";

  return { mesh, uniforms, material };
}

/** Shared GLSL snippets (noise, sky lookup, haze) used by sea + foam shaders. */

export const GLSL_NOISE = /* glsl */ `
  float hash21(vec2 p) {
    p = fract(p * vec2(233.34, 851.73));
    p += dot(p, p + 23.45);
    return fract(p.x * p.y);
  }

  float vnoise(vec2 p) {
    vec2 i = floor(p), f = fract(p);
    f = f * f * (3.0 - 2.0 * f);
    float a = hash21(i);
    float b = hash21(i + vec2(1.0, 0.0));
    float c = hash21(i + vec2(0.0, 1.0));
    float d = hash21(i + vec2(1.0, 1.0));
    return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
  }

  float fbm(vec2 p) {
    float v = 0.0, a = 0.5;
    for (int i = 0; i < 4; i++) {
      v += a * vnoise(p);
      p = p * 2.03 + vec2(11.7, -5.3);
      a *= 0.5;
    }
    return v;
  }
`;

/**
 * Cheap analytic sky used for reflections. Must agree with src/sky.js so the
 * sea reflects the same sky the camera sees.
 */
export function glslSky(sunDirJS) {
  return /* glsl */ `
  uniform vec3 uSunDir;
  uniform vec3 uSkyZenith;
  uniform vec3 uSkyMid;
  uniform vec3 uSkyHorizon;
  uniform vec3 uSkyHaze;
  uniform vec3 uSunGlowCol;

  vec3 skyLookup(vec3 dir) {
    float h = dir.y;
    vec3 col = mix(uSkyHorizon, uSkyMid, smoothstep(0.0, 0.22, h));
    col = mix(col, uSkyZenith, smoothstep(0.14, 0.85, h));
    col = mix(col, uSkyHaze, exp(-abs(h) * 13.0) * 0.55);
    float sd = max(dot(dir, uSunDir), 0.0);
    col += uSunGlowCol * (pow(sd, 42.0) * 0.55 + pow(sd, 6.0) * 0.16);
    col += vec3(1.0, 0.96, 0.87) * smoothstep(0.99885, 0.99945, sd) * 3.0;
    col = mix(col, uSkyHaze * 0.92, smoothstep(0.0, -0.10, h));
    return col;
  }
`;
}

export const GLSL_FOG = /* glsl */ `
  uniform vec3 uFogColor;
  uniform float uFogDensity;

  float hazeAmount(float dist) {
    return 1.0 - exp(-pow(max(dist, 0.0) * uFogDensity, 1.55));
  }
`;

export const FOG_DENSITY = 0.0062;

content.thinking:
Now ocean.js.

Note the sky uniforms must be shared between sky.js and ocean.js so they always agree. I'll build a `sharedUniforms` object in main and pass it. Simpler: ocean.js creates its own uniforms with the same values from PALETTE, and I expose `uniforms` for time updates. Both are static colors from the palette → identical. Fine, but let's centralize: create `src/sharedUniforms.js` exporting an object with uSunDir, sky colors, fog color, uTime. Both sky and ocean reference the SAME uniform objects (three allows sharing uniform value objects across materials). Let's do that — clean.

I'll restructure: sky.js accepts `shared` uniforms. Let me write shared.js:

```js
import * as THREE from "three";
import { PALETTE, SUN_DIR } from "./palette.js";
import { FOG_DENSITY } from "./glsl.js";

export const shared = {
  uTime: { value: 0 },
  uSunDir: { value: SUN_DIR.clone() },
  uSkyZenith: { value: new THREE.Color(PALETTE.zenith) },
  ...
  uFogColor: { value: new THREE.Color(PALETTE.haze) },
  uFogDensity: { value: FOG_DENSITY },
  uWaveAmp: { value: 1 },
  ...wavesUniforms()
};
```

Then sky material uniforms = {...subset} — but ShaderMaterial requires each used uniform to be present. If I pass the full shared object to both materials, unused uniforms are harmless (three just won't find a location; it warns? No — it silently ignores uniforms not in the program... Actually three's `WebGLUniforms.upload` iterates over the program's active uniforms and reads from the material's uniforms map; missing ones are skipped. Extra ones in the material are ignored. Safe.)

But careful: sharing the same uniform objects means both materials get the same values — exactly what I want.

Note: THREE.Color values in uniforms — with `outputColorSpace` sRGB and tone mapping, colors set from hex are in sRGB and three converts... For ShaderMaterial, `new THREE.Color("#hex")` stores the value in the working color space if `THREE.ColorManagement.enabled` (default true) — Color.set with a hex string converts sRGB → Linear-sRGB when ColorManagement is enabled. Yes: `Color.setStyle/setHex` applies SRGBToLinear when colorSpace is SRGBColorSpace (default for setHex). In r152+, `new THREE.Color('#hex')` → setStyle with SRGBColorSpace → converts to working (linear). Good, so uniform colors are linear, matching the shader output which then goes through tone mapping + colorspace conversion. 

Now ocean fragment shader details. Let me write it.

```glsl
varying vec3 vWorld;
varying vec3 vNormal;
varying float vCrest;
varying float vHeight;

void main(){
  vec3 V = normalize(cameraPosition - vWorld);
  vec3 N = normalize(vNormal);
  float dist = distance(cameraPosition, vWorld);

  // fine detail normal (fades with distance to avoid aliasing)
  float detail = 1.0 - smoothstep(18.0, 75.0, dist);
  vec2 np = vWorld.xz * 1.9 + vec2(uTime*0.35, uTime*0.22);
  float e = 0.09;
  float n0 = fbm(np), n1 = fbm(np + vec2(e,0.0)), n2 = fbm(np + vec2(0.0,e));
  vec3 dN = normalize(vec3(-(n1-n0)/e * 0.06, 1.0, -(n2-n0)/e * 0.06));
  N = normalize(N + (dN - vec3(0,1,0)) * detail);
  ...
}
```
Hmm, fbm with 4 octaves x3 = 12 noise calls, each 4 hash → heavy but at these resolutions OK. Let me use 2 octaves for the detail perturbation to keep cost down (vnoise x3 with 2 octaves). I'll write a lighter `ripple` function: `vnoise(p) * 0.6 + vnoise(p*2.3)*0.4`.

Colors:
- waterBody = mix(uDeep, uMid, smoothstep(-0.8, 1.2, vHeight)) then add uShallow near crests: mix with uCrestColor by smoothstep.
- reflection: R = reflect(-V, N); sky = skyLookup(R); fresnel = pow(1 - max(dot(N,V),0), 5) with F0 mix: f = 0.02 + 0.98*fresnel.
- color = mix(waterBody * ambientTint, sky, f)
- subsurface/translucency: sss = pow(max(dot(V, normalize(-uSunDir)),0)... hmm, when the camera looks toward the sun through the crest: L = sunDir, transmission term = pow(max(0.0, dot(-V, uSunDir)), 3.0)? Standard: `float backlight = pow(max(dot(V, -L), 0.0), 3.0)`? Let me use the common water trick: 
  `float sss = pow(clamp(dot(V, -L)*0.5+0.5, 0.0, 1.0), 3.0) * smoothstep(0.2, 1.4, vHeight)` and color += uSSSColor * sss * 0.6. With SSS color = warm teal-green #2fd3a0 * golden. Let's use a golden-green: "#3fd6a4" mixed with sun glow.
- specular: H = normalize(L + V); spec = pow(max(dot(N,H),0), 380) * 3.0 for the tight glitter + pow(...,40)*0.35 broader. Multiply by sun color. Add "glitter breakup": modulate the tight spec by a noise so it sparkles rather than being a smooth blob: spec *= mix(0.55, 1.4, vnoise(vWorld.xz*7.0 + uTime)).
- foam: 
  `float foamMask = smoothstep(0.42, 0.62, crestEnergy)` where crestEnergy = vCrest (accumulated steepness*s) — but let me instead base it on height + a noise field advected. 
  whitecaps: `float wc = smoothstep(0.55, 0.95, vCrest * 1.6)`; hmm need to know the range of vCrest. crest = Σ steepness * sin(f). Max = Σ steepness = 0.235+0.165+0.125+0.07+0.045+0.028 = 0.668 (with amp=1). Typical crest values when several waves align: ~0.4. So whitecap threshold: smoothstep(0.30, 0.55, crest).
  foam texture: fbm(vWorld.xz * 0.9 - dir*uTime) → stretch along wave direction for streaks.
