import * as THREE from "three";
import { PALETTE, SUN_DIR } from "./palette.js";
import { wavesUniforms, wavesGLSL } from "./waves.js";
import { GLSL_NOISE, GLSL_FOG, glslSky, FOG_DENSITY } from "./glsl.js";

/**
 * Uniform objects shared by the sky dome, the ocean and the foam trail so that
 * every surface agrees on where the sun is, what colour the haze is and what
 * moment in time it is.
 */
export const shared = {
  uTime: { value: 0 },
  uWaveAmp: { value: 1 },
  uSunDir: { value: SUN_DIR.clone() },
  uSkyZenith: { value: new THREE.Color(PALETTE.zenith) },
  uSkyMid: { value: new THREE.Color(PALETTE.midSky) },
  uSkyHorizon: { value: new THREE.Color(PALETTE.horizonSky) },
  uSkyHaze: { value: new THREE.Color(PALETTE.haze) },
  uSunGlowCol: { value: new THREE.Color(PALETTE.sunGlow) },
  uFogColor: { value: new THREE.Color(PALETTE.haze) },
  uFogDensity: { value: FOG_DENSITY },
  ...wavesUniforms(),
};

/* ------------------------------------------------------------------ */

const OCEAN_VERT = /* glsl */ `
  ${wavesGLSL()}
  varying vec3 vWorld;
  varying vec3 vNrm;
  varying float vCrest;
  varying float vHeight;
  varying float vDist;

  void main() {
    vec2 p = vec2(position.x, position.z);
    vec3 nrm;
    float crest;
    vec3 displaced = gerstnerSea(p, uTime, nrm, crest);

    vWorld = displaced;
    vNrm = nrm;
    vCrest = crest;
    vHeight = displaced.y;
    vDist = distance(cameraPosition, displaced);

    gl_Position = projectionMatrix * viewMatrix * vec4(displaced, 1.0);
  }
`;

const OCEAN_FRAG = /* glsl */ `
  precision highp float;
  ${GLSL_NOISE}
  ${glslSky()}
  ${GLSL_FOG}
  uniform float uTime;
  uniform vec3 uDeep;
  uniform vec3 uMid;
  uniform vec3 uShallow;
  uniform vec3 uFoamCol;
  uniform vec3 uSSS;
  uniform vec3 uSunCol;

  varying vec3 vWorld;
  varying vec3 vNrm;
  varying float vCrest;
  varying float vHeight;
  varying float vDist;

  float ripple(vec2 p) {
    return vnoise(p) * 0.62 + vnoise(p * 2.37 + 4.1) * 0.38;
  }

  void main() {
    vec3 V = normalize(cameraPosition - vWorld);
    vec3 N = normalize(vNrm);
    vec3 L = normalize(uSunDir);

    // --- micro surface detail, faded out with distance -------------------
    float detail = 1.0 - smoothstep(14.0, 62.0, vDist);
    if (detail > 0.001) {
      vec2 np = vWorld.xz * 2.1 + vec2(uTime * 0.42, -uTime * 0.27);
      float e = 0.16;
      float h0 = ripple(np);
      float hx = ripple(np + vec2(e, 0.0));
      float hz = ripple(np + vec2(0.0, e));
      N = normalize(N + vec3(-(hx - h0), 0.0, -(hz - h0)) * (0.85 * detail));
    }

    float ndv = clamp(dot(N, V), 0.0, 1.0);

    // --- body colour: deep troughs, teal shoulders, bright crests --------
    vec3 body = mix(uDeep, uMid, smoothstep(-1.5, 1.1, vHeight));
    body = mix(body, uShallow, smoothstep(0.35, 1.9, vHeight) * 0.75);

    // --- sky reflection with fresnel -------------------------------------
    vec3 R = reflect(-V, N);
    vec3 sky = skyLookup(R);
    float fres = 0.022 + 0.978 * pow(1.0 - ndv, 5.0);
    vec3 col = mix(body, sky, clamp(fres, 0.0, 1.0));

    // --- translucency where light passes through a thin crest ------------
    float back = pow(clamp(dot(V, -L) * 0.5 + 0.5, 0.0, 1.0), 4.0);
    float thin = smoothstep(0.15, 1.7, vHeight) * (0.45 + 0.55 * vCrest);
    col += uSSS * back * thin * 0.85;

    // --- sun specular: tight glitter + soft sheen ------------------------
    vec3 H = normalize(L + V);
    float ndh = max(dot(N, H), 0.0);
    float sparkle = mix(0.35, 1.65, vnoise(vWorld.xz * 6.5 + uTime * 0.6));
    float specTight = pow(ndh, 620.0) * 5.5 * sparkle;
    float specWide = pow(ndh, 34.0) * 0.42;
    float glintMask = smoothstep(0.0, 0.35, ndh);
    col += uSunCol * (specTight + specWide) * glintMask;

    // --- whitecaps & chop foam -------------------------------------------
    float streak = fbm(vWorld.xz * 0.42 + vec2(-uTime * 0.85, uTime * 0.12));
    float wc = smoothstep(0.24, 0.52, vCrest + (streak - 0.5) * 0.30);
    float chop = smoothstep(0.55, 0.95, streak) * smoothstep(-0.1, 0.6, vCrest) * 0.35;
    float bubbles = smoothstep(0.62, 0.88, fbm(vWorld.xz * 3.1 + uTime * 0.5));
    float foam = clamp(wc * (0.45 + 0.75 * bubbles) + chop * bubbles, 0.0, 1.0);
    foam *= 1.0 - smoothstep(120.0, 260.0, vDist);   // no foam specks in the haze
    vec3 foamLit = mix(uFoamCol, uFoamCol * 0.72 + uSunCol * 0.35, 1.0 - ndv);
    col = mix(col, foamLit, foam);

    // --- haze to the horizon ---------------------------------------------
    col = mix(col, uFogColor, hazeAmount(vDist));

    gl_FragColor = vec4(col, 1.0);
    #include <tonemapping_fragment>
    #include <colorspace_fragment>
  }
`;

/* ------------------------------------------------------------------ */

/** Ring of water from `inner` to `outer` with geometric radial spacing. */
function farRingGeometry(inner, outer, thetaSegs, radialSegs) {
  const positions = [];
  const indices = [];
  const ratio = outer / inner;

  for (let j = 0; j <= radialSegs; j++) {
    const r = inner * Math.pow(ratio, j / radialSegs);
    for (let i = 0; i <= thetaSegs; i++) {
      const a = (i / thetaSegs) * Math.PI * 2;
      positions.push(Math.cos(a) * r, 0, Math.sin(a) * r);
    }
  }
  const row = thetaSegs + 1;
  for (let j = 0; j < radialSegs; j++) {
    for (let i = 0; i < thetaSegs; i++) {
      const a = j * row + i;
      const b = a + 1;
      const c = a + row;
      const d = c + 1;
      indices.push(a, c, b, b, c, d);
    }
  }

  const geo = new THREE.BufferGeometry();
  geo.setAttribute("position", new THREE.Float32BufferAttribute(positions, 3));
  geo.setIndex(indices);
  geo.computeBoundingSphere();
  return geo;
}

export function createOcean() {
  const material = new THREE.ShaderMaterial({
    uniforms: {
      ...shared,
      uDeep: { value: new THREE.Color(PALETTE.deepWater) },
      uMid: { value: new THREE.Color(PALETTE.midWater) },
      uShallow: { value: new THREE.Color(PALETTE.shallowWater) },
      uFoamCol: { value: new THREE.Color(PALETTE.foam) },
      uSSS: { value: new THREE.Color("#2fd0a2") },
      uSunCol: { value: new THREE.Color("#ffe6bb") },
    },
    vertexShader: OCEAN_VERT,
    fragmentShader: OCEAN_FRAG,
    side: THREE.FrontSide,
    fog: false,
  });

  const hero = new THREE.PlaneGeometry(250, 250, 250, 250);
  hero.rotateX(-Math.PI / 2);
  const heroMesh = new THREE.Mesh(hero, material);
  heroMesh.name = "ocean-hero";
  heroMesh.frustumCulled = false;

  const far = farRingGeometry(110, 3200, 168, 40);
  const farMesh = new THREE.Mesh(far, material);
  farMesh.name = "ocean-far";
  farMesh.frustumCulled = false;

  const group = new THREE.Group();
  group.add(heroMesh, farMesh);

  return { group, material, shared };
}

import * as THREE from "three";
import { PALETTE } from "./palette.js";

const clamp = (v, a, b) => Math.min(b, Math.max(a, v));
const sstep = (e0, e1, x) => {
  const t = clamp((x - e0) / (e1 - e0 || 1e-6), 0, 1);
  return t * t * (3 - 2 * t);
};

/**
 * A surfboard built as a swept parametric surface.
 *   local frame: +Z = nose, +X = right rail, +Y = up, y = 0 is the waterline
 *   u = 0 at the tail, u = 1 at the nose tip
 */
export const BOARD = {
  length: 4.9,
  width: 1.02,
  thickness: 0.19,
  tailZ: 0, // computed below
  noseZ: 0,
};
BOARD.tailZ = -BOARD.length * 0.42;
BOARD.noseZ = BOARD.length * 0.58;

function widthAt(u) {
  const W = BOARD.width;
  const t = u - 0.42;
  const half = t < 0 ? 0.54 : 0.70; // tail is shorter than the nose
  const tn = clamp(Math.abs(t) / half, 0, 1);
  const e = t < 0 ? 2.1 : 2.6;
  return Math.max(0.004, W * Math.max(0, 1 - Math.pow(tn, e)));
}

function thicknessAt(u) {
  const w = widthAt(u) / BOARD.width;
  return BOARD.thickness * (0.28 + 0.72 * Math.pow(w, 0.55));
}

function rockerAt(u) {
  const nose = 0.62 * Math.pow(clamp((u - 0.52) / 0.48, 0, 1), 2.3);
  const tail = 0.24 * Math.pow(clamp((0.30 - u) / 0.30, 0, 1), 2.0);
  return nose + tail;
}

function zAt(u) {
  return BOARD.tailZ + u * BOARD.length;
}

const RADIAL = 30;
const LONG = 110;

function boardGeometry() {
  const pos = [];
  const col = [];
  const idx = [];

  const deck = new THREE.Color(PALETTE.boardDeck);
  const bottom = new THREE.Color(PALETTE.boardBottom);
  const stripe = new THREE.Color(PALETTE.boardStripe);
  const rail = new THREE.Color(PALETTE.boardRail);
  const pad = new THREE.Color("#2b3b45");
  const tmp = new THREE.Color();

  // pass 1: find the lowest point so the board rests exactly on y = 0
  let minY = Infinity;
  for (let i = 0; i <= LONG; i++) {
    const u = i / LONG;
    minY = Math.min(minY, rockerAt(u) - 0.58 * thicknessAt(u));
  }

  for (let i = 0; i <= LONG; i++) {
    const u = i / LONG;
    const hw = widthAt(u) * 0.5;
    const th = thicknessAt(u);
    const z = zAt(u);
    const rock = rockerAt(u) - minY;

    for (let j = 0; j <= RADIAL; j++) {
      const a = (j / RADIAL) * Math.PI * 2;
      const sx = Math.sin(a);
      const sy = Math.cos(a);

      const x = hw * Math.sign(sx) * Math.pow(Math.abs(sx), 0.70);
      const y =
        sy >= 0
          ? rock + th * 0.42 * Math.pow(sy, 0.72)
          : rock - th * 0.58 * Math.pow(-sy, 1.7);

      pos.push(x, y, z);

      // --- paint ---------------------------------------------------------
      const xn = clamp(x / Math.max(hw, 1e-4), -1, 1);
      tmp.copy(bottom).lerp(deck, sstep(-0.06, 0.26, sy));
      tmp.lerp(rail, (1 - sstep(0.0, 0.16, Math.abs(sy))) * 0.9);

      // deck stringer stripe
      const st = (1 - sstep(0.075, 0.15, Math.abs(xn))) * sstep(0.06, 0.3, sy);
      tmp.lerp(stripe, st * 0.95);

      // wax / traction pad where the feet land
      const pd =
        sstep(0.26, 0.33, u) *
        (1 - sstep(0.60, 0.66, u)) *
        (1 - sstep(0.40, 0.56, Math.abs(xn))) *
        sstep(0.12, 0.4, sy);
      tmp.lerp(pad, pd * 0.85);

      // warm fade toward the nose on the bottom
      tmp.lerp(new THREE.Color("#f6d9a8"), sstep(0.72, 1.0, u) * (1 - sstep(0.0, 0.4, sy)) * 0.55);

      col.push(tmp.r, tmp.g, tmp.b);
    }
  }

  const row = RADIAL + 1;
  for (let i = 0; i < LONG; i++) {
    for (let j = 0; j < RADIAL; j++) {
      const a = i * row + j;
      const b = a + 1;
      const c = a + row;
      const d = c + 1;
      idx.push(a, c, b, b, c, d);
    }
  }

  const geo = new THREE.BufferGeometry();
  geo.setAttribute("position", new THREE.Float32BufferAttribute(pos, 3));
  geo.setAttribute("color", new THREE.Float32BufferAttribute(col, 3));
  geo.setIndex(idx);
  geo.computeVertexNormals();
  geo.computeBoundingSphere();
  return geo;
}

function finGeometry() {
  const shape = new THREE.Shape();
  shape.moveTo(0, 0);
  shape.bezierCurveTo(0.06, -0.20, 0.30, -0.42, 0.62, -0.46);
  shape.bezierCurveTo(0.52, -0.30, 0.44, -0.14, 0.46, 0.0);
  shape.lineTo(0, 0);

  const geo = new THREE.ExtrudeGeometry(shape, {
    depth: 0.045,
    bevelEnabled: true,
    bevelSize: 0.018,
    bevelThickness: 0.018,
    bevelSegments: 3,
    curveSegments: 12,
  });
  geo.rotateY(Math.PI / 2); // thin along X
  geo.translate(-0.0225, 0, 0);
  geo.computeVertexNormals();
  return geo;
}

export function createSurfboard() {
  const group = new THREE.Group();

  const hull = new THREE.Mesh(
    boardGeometry(),
    new THREE.MeshStandardMaterial({
      vertexColors: true,
      roughness: 0.30,
      metalness: 0.0,
      envMapIntensity: 1.0,
    })
  );
  hull.name = "board-hull";
  group.add(hull);

  const finMat = new THREE.MeshStandardMaterial({
    color: new THREE.Color(PALETTE.fin),
    roughness: 0.35,
    metalness: 0.05,
  });

  const fin = new THREE.Mesh(finGeometry(), finMat);
  fin.scale.setScalar(0.95);
  fin.position.set(0, 0.02, zAt(0.14));
  fin.rotation.x = -0.12;
  group.add(fin);

  // two small side bites
  for (const s of [-1, 1]) {
    const bite = new THREE.Mesh(finGeometry(), finMat);
    bite.scale.set(0.42, 0.42, 0.42);
    bite.position.set(s * 0.16, 0.015, zAt(0.235));
    bite.rotation.set(-0.05, 0, s * 0.32);
    group.add(bite);
  }

  // leash plug at the tail
  const plug = new THREE.Mesh(
    new THREE.CylinderGeometry(0.045, 0.05, 0.05, 12),
    new THREE.MeshStandardMaterial({ color: 0x2a2a2e, roughness: 0.6 })
  );
  plug.position.set(0, 0.055, zAt(0.045));
  group.add(plug);

  group.userData.zAt = zAt;
  return group;
}

